changeSet.sql:
DO $do$
DECLARE
    current_data_type TEXT;
    current_maximum_length INTEGER;
BEGIN
    SELECT data_type, character_maximum_length
      INTO current_data_type, current_maximum_length
      FROM information_schema.columns
     WHERE table_schema = current_schema()
       AND table_name = 'portal_menu'
       AND column_name = 'last_modified_by';

    IF NOT FOUND THEN
        RAISE EXCEPTION 'portal_menu.last_modified_by is missing';
    ELSIF current_data_type = 'character varying' AND current_maximum_length = 50 THEN
        ALTER TABLE portal_menu ALTER COLUMN last_modified_by TYPE VARCHAR(100);
    ELSIF current_data_type = 'character varying' AND current_maximum_length >= 100 THEN
        NULL;
    ELSIF current_data_type = 'text' THEN
        NULL;
    ELSE
        RAISE EXCEPTION 'portal_menu.last_modified_by has unsupported type/width: %/%',
            current_data_type, current_maximum_length;
    END IF;
END
$do$;
